      "operation": "sketch_slot",
      "description": "绘制第一个小槽，位于接近外缘处（半径25mm处）"
    },
    {
      "operation": "close_sketch",
      "description": "关闭草图"
    },
    {
      "operation": "feature_cut_extrusion",
      "description": "切除拉伸创建第一个小槽（贯穿）"
    },
    {
      "operation": "feature_circular_pattern",
      "description": "圆周阵列小槽，均布12个，360度"
    }
  ],
  "user_intent": "创建一个直径60mm、厚8mm的圆盘零件，中心有直径12mm的贯穿孔，并在接近外缘处均布12个相同的小贯穿槽（槽形为直线槽）"
}

{
  "user_intent": "创建一个圆形法兰盘：直径100mm，厚度12mm，中心有直径30mm的贯穿孔，节圆直径80mm上均布6个直径8mm的贯穿孔",
  "notes": "单位换算：所有尺寸转换为米。法兰直径100mm=0.1m（半径0.05m），厚度12mm=0.012m，中心孔直径30mm=0.03m（半径0.015m），节圆直径80mm=0.08m（半径0.04m），螺栓孔直径8mm=0.008m（半径0.004m）。建模策略：在前视基准面上画法兰轮廓（带中心孔），拉伸凸台；然后在顶面画6个螺栓孔，用圆周阵列生成。",
  "steps": [
    {
      "operation": "new_part"
    },
    {
      "operation": "select_plane"
    },
    {
      "operation": "sketch_circle"
    },
    {
      "operation": "sketch_circle"
    },
    {
      "operation": "close_sketch"
    },
    {
      "operation": "feature_extrusion"
    },
    {
      "operation": "select_face_and_sketch"
    },
    {
      "operation": "sketch_circle"
    },
    {
      "operation": "feature_cut_extrusion"
    },
    {
      "operation": "feature_circular_pattern"
    }
  ]
}

